public class ProductionDiagnosticHandler extends SimpleChannelInboundHandler<HttpObject> {
    private static final Logger log = LoggerFactory.getLogger(ProductionDiagnosticHandler.class);

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, HttpObject msg) {
        try {
            // Process incoming NIO payload
        } catch (Exception e) {
            String traceId = ctx.channel().attr(AttributeKey.<String>valueOf("traceId")).get();
            log.error("Outage detected on channel: {} with TraceID: {}", ctx.channel().id(), traceId, e);

            // Write safe error response and propagate backpressure
            FullHttpResponse response = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.INTERNAL_SERVER_ERROR);
            ctx.writeAndFlush(response).addListener(ChannelFutureListener.CLOSE);
        }
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
        if (cause instanceof IOException) {
            log.warn("Client forcibly closed connection or network reset: {}", cause.getMessage());
        } else {
            log.error("Critical NIO pipeline exception", cause);
        }
        ctx.close();
    }
}
